/* rtp.glb embedded for hosts that do not serve .glb files: decoded into a blob URL at load time (make_bundle.py). */
(function(){var b=atob("");var u=new Uint8Array(b.length);for(var i=0;i<b.length;i++)u[i]=b.charCodeAt(i);window.RTP_GLB_URL=URL.createObjectURL(new Blob([u],{type:'model/gltf-binary'}));})();
